    if (k === 1) return Rc(18, 48, 28, 6, fl(0.25)) + Rc(12, 54, 40, 4, fl(0.2)) + P('M24 48Q20 34 28 28L36 28Q44 34 40 48Z', fl(0.22)) + C(32, 20, 7, fl(0.2)) + P('M32 10v3') + P('M24 34L16 44M40 34L48 44') + P('M20 58L14 62M44 58L50 62', ' opacity="0"') + P('M6 62H58');
